-- FINANCIA Phase 2 — security grants and foreign-key index hardening
-- Generated by: supabase migration new phase2_security_and_index_hardening
-- Target PostgreSQL: 17
-- This migration removes unsafe default object privileges from client roles.

BEGIN;

-- ---------------------------------------------------------------------------
-- Remove inherited/default table privileges from client roles. RLS does not
-- protect TRUNCATE, and clients must never be able to create table triggers.
-- Re-grant only the exact operations used by the application.
-- ---------------------------------------------------------------------------

REVOKE ALL PRIVILEGES ON TABLE
  public.households,
  public.profiles,
  public.household_members,
  public.ledger_accounts,
  public.transaction_categories,
  public.transactions,
  public.financial_accounts,
  public.journal_entries,
  public.journal_lines
FROM PUBLIC, anon, authenticated;

GRANT SELECT ON TABLE public.households TO authenticated;
GRANT UPDATE (name, base_currency, timezone)
  ON TABLE public.households TO authenticated;

GRANT SELECT ON TABLE public.profiles TO authenticated;
GRANT UPDATE (display_name, avatar_path)
  ON TABLE public.profiles TO authenticated;

GRANT SELECT ON TABLE public.household_members TO authenticated;

GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE
  public.ledger_accounts,
  public.transaction_categories,
  public.transactions,
  public.journal_entries,
  public.journal_lines
TO authenticated;

GRANT SELECT, INSERT, DELETE ON TABLE public.financial_accounts TO authenticated;
GRANT UPDATE (
  account_name,
  account_type,
  provider_name,
  owner_attribution,
  account_number_last4,
  currency_code,
  opening_balance_transaction_id,
  is_active
) ON TABLE public.financial_accounts TO authenticated;

-- Keep the trusted server-side role usable for provisioning and Edge Functions.
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE
  public.households,
  public.profiles,
  public.household_members,
  public.ledger_accounts,
  public.transaction_categories,
  public.transactions,
  public.financial_accounts,
  public.journal_entries,
  public.journal_lines
TO service_role;

-- ---------------------------------------------------------------------------
-- Index every referencing side of the foreign keys surfaced by Supabase
-- Performance Advisor. These are additive and do not change row semantics.
-- ---------------------------------------------------------------------------

CREATE INDEX IF NOT EXISTS households_created_by_idx
  ON public.households (created_by)
  WHERE created_by IS NOT NULL;

CREATE INDEX IF NOT EXISTS household_members_invited_by_idx
  ON public.household_members (invited_by)
  WHERE invited_by IS NOT NULL;

CREATE INDEX IF NOT EXISTS financial_accounts_created_by_idx
  ON public.financial_accounts (created_by);

CREATE INDEX IF NOT EXISTS financial_accounts_opening_transaction_fk_idx
  ON public.financial_accounts (household_id, opening_balance_transaction_id)
  WHERE opening_balance_transaction_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS ledger_accounts_parent_fk_idx
  ON public.ledger_accounts (household_id, parent_account_id)
  WHERE parent_account_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS transaction_categories_parent_fk_idx
  ON public.transaction_categories (household_id, parent_category_id)
  WHERE parent_category_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS transactions_category_fk_idx
  ON public.transactions (household_id, category_id)
  WHERE category_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS transactions_created_by_idx
  ON public.transactions (created_by);

CREATE INDEX IF NOT EXISTS transactions_updated_by_idx
  ON public.transactions (updated_by)
  WHERE updated_by IS NOT NULL;

CREATE INDEX IF NOT EXISTS transactions_voided_by_idx
  ON public.transactions (voided_by)
  WHERE voided_by IS NOT NULL;

CREATE INDEX IF NOT EXISTS journal_entries_posted_by_idx
  ON public.journal_entries (posted_by)
  WHERE posted_by IS NOT NULL;

CREATE INDEX IF NOT EXISTS journal_entries_reversal_fk_idx
  ON public.journal_entries (household_id, reversal_of_entry_id)
  WHERE reversal_of_entry_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS journal_entries_transaction_fk_idx
  ON public.journal_entries (household_id, transaction_id);

CREATE INDEX IF NOT EXISTS journal_lines_category_fk_idx
  ON public.journal_lines (household_id, category_id)
  WHERE category_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS journal_lines_entry_fk_idx
  ON public.journal_lines (household_id, journal_entry_id);

-- ---------------------------------------------------------------------------
-- Close the Security Advisor finding on the pre-existing RLS event-trigger
-- helper. The trigger remains owned by postgres; client roles cannot call the
-- SECURITY DEFINER function as an RPC. Verify the event trigger still enables
-- RLS on a disposable public table after the privilege change.
-- ---------------------------------------------------------------------------

REVOKE EXECUTE ON FUNCTION public.rls_auto_enable()
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.rls_auto_enable() TO postgres;

CREATE TABLE public.financia_rls_probe (
  id integer PRIMARY KEY
);

DO $test$
DECLARE
  v_rls_enabled boolean;
BEGIN
  SELECT c.relrowsecurity
  INTO v_rls_enabled
  FROM pg_class AS c
  JOIN pg_namespace AS n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relname = 'financia_rls_probe';

  IF COALESCE(v_rls_enabled, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'RLS auto-enable event trigger failed after helper EXECUTE was restricted';
  END IF;
END;
$test$;

DROP TABLE public.financia_rls_probe;

COMMIT;
